static String generateBuildGradle(String groupId, String version, List<String> deps) {
    StringBuilder sb = new StringBuilder("plugins { id 'java' }\n");
    sb.append("group = '").append(groupId).append("'\n");
    sb.append("version = '").append(version).append("'\n");
    sb.append("dependencies {\n");
    for (String d : deps) sb.append("    implementation '").append(d).append("'\n");
    sb.append("}\n");
    return sb.toString();
}
System.out.println(generateBuildGradle("com.example", "1.0.0", List.of("com.google.code.gson:gson:2.11.0")));

